'use strict';
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  home:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  folder:'<path d="M3 7a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
  file:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M8 13h8M8 17h5"/>',
  disk:'<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="12" cy="11" r="4"/><path d="m12 11 5 5M7 18h2"/>',
  camera:'<rect x="3" y="6" width="13" height="13" rx="3"/><path d="m16 10 5-3v11l-5-3"/>',
  users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-4-5"/>',
  share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 10 6-4M9 14l6 4"/>',
  server:'<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6h.01M7 17h.01M11 6h6M11 17h6"/>',
  backup:'<path d="M4 9V4m0 0h5M4 4l4 4a8 8 0 1 1-3 8"/><path d="M12 8v5l3 2"/>',
  activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
  check:'<path d="m5 12 4 4L19 6"/>',
  arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
  upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5"/>',
  download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',
  rename:'<path d="m16 3 5 5L9 20l-6 1 1-6ZM13 6l5 5"/>',
  plus:'<path d="M12 4v16M4 12h16"/>',
  close:'<path d="m6 6 12 12M18 6 6 18"/>',
  logout:'<path d="M9 4H4v16h5M9 12h12m-4-4 4 4-4 4"/>',
  left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',up:'<path d="m5 15 7-7 7 7"/>',down:'<path d="m5 9 7 7 7-7"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',
  lock:'<rect x="4" y="10" width="16" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
  memory:'<rect x="5" y="5" width="14" height="14" rx="2"/><path d="M9 1v4m6-4v4M9 19v4m6-4v4M1 9h4m-4 6h4m14-6h4m-4 6h4"/>',
};
const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.file}</svg>`;
const sizes = n => { if (!Number.isFinite(Number(n))) return '—'; let x=Number(n),i=0;while(x>=1024 && i<4){x/=1024;i++;}return `${x.toLocaleString('fr-FR',{maximumFractionDigits:i ? 1 : 0})} ${['o','Kio','Mio','Gio','Tio'][i]}`; };
const date = t => new Date(t*1000).toLocaleString('fr-FR',{timeZone:user?.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone,day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const clock = t => new Date(t*1000).toLocaleTimeString('fr-FR',{timeZone:user?.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone,hour:'2-digit',minute:'2-digit'});
const titles = {setup:'Première configuration',home:'Vue d’ensemble',files:'Fichiers',camera:'Surveillance',storage:'Stockage',native:'Volumes natifs',shares:'Partages SMB',users:'Utilisateurs',services:'Services',backups:'Sauvegardes',snapshots:'Snapshots',events:'Journal d’activité',trash:'Corbeille'};
let user=null, page='home', area='fichiers', currentPath='', currentOverview=null, currentSmb=null, webUsers=[], cameraSettings=null, refreshTimer=null, imageTimer=null;
let modalSubmit=null, fileAreas=[], protectionSources=[], sessionGeneration=0;

function toast(text,error=false){ const e=$('#toast');e.textContent=text;e.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.className='',5000); }
async function api(path,body){
 const generation=sessionGeneration;
 const options=body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':user?.csrf || ''},body:JSON.stringify(body)};
 const r=await fetch('/api/'+path,options);
 let data;try{data=await r.json();}catch{throw new Error('Le serveur ne répond pas comme prévu.');}
 if(generation!==sessionGeneration){const error=new Error('Requête devenue obsolète.');error.name='AbortError';throw error;}
 if(!r.ok){const error=new Error(data.error || 'Opération non aboutie.');error.status=r.status;if(r.status===401 && path!=='login')login(error.message);throw error;}
 return data;
}
function button(action,label,ic,cls='',attrs=''){return `<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label?`<span>${label}</span>`:''}</button>`;}
function empty(text,ic='folder'){return `<div class="empty">${icon(ic)}<div>${esc(text)}</div></div>`;}
function heading(title,description,actions=''){return `<div class="pageheading"><div><p class="eyebrow">VOTRE NAS, EN AUTONOMIE</p><h1>${title}</h1><p>${description}</p></div><div class="row">${actions}</div></div>`;}
function table(headers,rows){return `<div class="tablewrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;}
function field(label,name,value='',type='text',note=''){return `<div class="field"><label for="field-${name}">${label}</label><input id="field-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='password'?'autocomplete="new-password"':'autocomplete="off"'} required>${note?`<small>${note}</small>`:''}</div>`;}

function shell(){
const nav=[...(user.role==='admin'?[['setup','check']]:[]),['home','home'],['files','folder'],['camera','camera'],['storage','disk'],['native','disk'],['shares','share'],['users','users'],['services','server'],['backups','backup'],['snapshots','backup'],['events','activity']];
$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home"><span class="brandmark">${icon('server')}</span><span class="brandname">nacre</span></a><div class="brandnote">NAS AUTONOME</div><div class="nav-title">Espace personnel</div><nav class="nav">${nav.map(([p,i])=>`<button data-page="${p}" class="${page===p?'active':''}">${icon(i)}<span>${titles[p]}</span></button>`).join('')}</nav><div class="side-bottom"><span class="statusdot"></span>Connexion locale<strong id="side-host">NAS</strong>Vos données restent chez vous.</div></aside><div class="main"><header class="topbar"><div class="crumb">Espace de travail<span id="crumb">${titles[page]}</span></div><div class="topright"><time id="topclock">${date(Date.now()/1000)}</time><div class="account"><div class="avatar">${esc(user.name.slice(0,1).toUpperCase())}</div><span>${esc(user.name)}</span><button data-action="logout" aria-label="Se déconnecter">${icon('logout')}</button></div></div></header><main class="content" id="content"></main></div></div>`;
}
function login(message=''){sessionGeneration++;user=null;clearInterval(refreshTimer);clearInterval(imageTimer);$('#app').innerHTML=`<div class="login-wrap"><section class="login-art"><div class="brand"><span class="brandmark">${icon('server')}</span>nacre</div><div><h1>Votre espace.<br>Vos données.<br>Votre contrôle.</h1><p>Stockage et vidéosurveillance réunis dans une console locale, sur votre NAS.</p></div><div class="lower">NAS AUTONOME · ACCÈS LOCAL</div></section><section class="login-form"><form id="login-form"><p class="eyebrow">BIENVENUE CHEZ VOUS</p><h2>Connexion à votre NAS</h2><p class="muted">Utilisez votre compte de console Nacre.</p>${field('Identifiant','username','admin')}${field('Mot de passe','password','','password')}<p class="error" id="login-error">${esc(message)}</p><button class="primary" type="submit">Ouvrir mon espace</button><p class="capacity-note">Les identifiants provisoires sont disponibles dans le terminal utilisé pour préparer Nacre.</p></form></section></div>`;}
async function go(next){if(user?.setup_required)next='setup';clearInterval(imageTimer);page=next;location.hash=next;if(!user)return;document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===page));$('#crumb').textContent=titles[page]||titles.home;$('#content').innerHTML='<div class="empty">Chargement de votre espace…</div>';try{await render();}catch(e){const content=$('#content');if(!user||!content||e.name==='AbortError')return;content.innerHTML=empty(e.message,'activity');toast(e.message,true);}}

async function render(){switch(page){case 'setup':return renderSetup();case 'home':return renderHome();case 'files':return renderFiles();case 'camera':return renderCamera();case 'storage':return renderStorage();case 'native':return renderNative();case 'shares':return renderShares();case 'users':return renderUsers();case 'services':return renderServices();case 'backups':return renderBackups();case 'snapshots':return renderSnapshots();case 'events':return renderEvents();case 'trash':return renderTrash();default:return go('home');}}

async function renderHome(){clearInterval(imageTimer);const d=await api('overview');currentOverview=d;const running=d.services.filter(s=>s.state==='running').length,used=d.disk.used/d.disk.total*100;$('#side-host').textContent=d.host;$('#content').innerHTML=heading('Tout est à sa place.','Un regard sur vos fichiers, votre stockage et votre caméra.',`<span class="badge">${icon('check')}${!d.services_available?'Services à installer ou à démarrer':running===2?'Services en ligne':`${running} service(s) actif(s)`}</span>`)+`<div class="cards"><section class="card cardpad"><div class="metrichead">Stockage disponible${icon('disk')}</div><div class="metric">${sizes(d.disk.free)}<small>sur ${sizes(d.disk.total)}</small></div><div class="progress"><i id="diskbar"></i></div><p class="metricfoot">${used.toFixed(1).replace('.',',')} % du volume utilisé</p></section><section class="card cardpad"><div class="metrichead">Mémoire système${icon('memory')}</div><div class="metric">${sizes(d.memory.used)}<small>sur ${sizes(d.memory.total)}</small></div><div class="progress"><i id="membar"></i></div><p class="metricfoot">Mémoire utilisée par l’ensemble de NAS</p></section><section class="card cardpad"><div class="metrichead">Charge du processeur${icon('activity')}</div><div class="metric">${d.load[0].toFixed(2).replace('.',',')}<small>sur ${d.cpus} cœurs</small></div><div class="progress"><i id="cpubar"></i></div><p class="metricfoot">Charge moyenne sur la dernière minute</p></section></div><div class="overview-grid"><section class="card"><div class="cardhead"><h2>Un œil sur votre espace</h2><span class="badge ${d.camera.camera_fps>0?'':'warn'}"><span class="statusdot"></span>${d.camera.camera_fps>0?'Caméra connectée':'En attente'}</span></div><div class="cameraimage"><img src="/api/camera/snapshot" alt="Vue actuelle de la caméra Tapo C530WS" id="camera-preview"><span class="live-tag"><span class="statusdot"></span>TAPO C530WS</span><div class="cam-caption">Caméra principale</div></div><div class="camerafooter"><span>Actualisation toutes les 5 secondes</span><button class="small" data-page="camera">Ouvrir la surveillance →</button></div></section><div class="stack"><section class="card"><div class="cardhead"><h2>Vos services</h2><span class="muted">${running}/2 actifs</span></div>${d.services.map(s=>`<div class="service"><span class="appicon">${icon(s.name==='video'?'camera':'folder')}</span><div class="detail"><h3>${s.name==='video'?'Vidéosurveillance':'Partage de fichiers'}</h3><p>${s.name==='video'?'Frigate · enregistrement local':'Samba · protocole SMB'}</p></div><span class="badge ${s.state==='running'?'':'dim'}">${s.state==='running'?'En ligne':'Arrêté'}</span></div>`).join('')}</section><section class="card cardpad"><h2>À portée de main</h2><p class="muted">Les outils de votre quotidien.</p><div class="quickactions"><button data-page="files">${icon('folder')}Mes fichiers</button><button data-page="shares">${icon('share')}Partages</button><button data-page="backups">${icon('backup')}Sauvegardes</button></div></section></div><section class="card wide"><div class="cardhead"><h2>Activité récente</h2><a href="#events" data-page="events">Tout le journal →</a></div>${d.events.length?d.events.slice(0,4).map(event=>`<div class="event"><time>${clock(event.ts)}</time><span>${esc(event.action)}</span><span class="actor">${esc(event.username)}</span></div>`).join(''):empty('Les actions effectuées dans cette console apparaîtront ici.','activity')}</section></div><footer class="footnote"><span>${icon('lock')} Accès local via votre tunnel SSH</span><span>${esc(d.host)} · Nacre 0.6-dev</span></footer>`;$('#diskbar').style.width=used+'%';$('#membar').style.width=(d.memory.used/d.memory.total*100)+'%';$('#cpubar').style.width=Math.min(100,d.load[0]/d.cpus*100)+'%';imageTimer=setInterval(()=>{const img=$('#camera-preview');if(img)img.src='/api/camera/snapshot?t='+Date.now();},5000);}

async function renderFiles(){
 fileAreas=await api('areas');
 if(!fileAreas.some(a=>a.id===area)){area='fichiers';currentPath='';toast('Le volume est indisponible. Retour aux fichiers partagés.',true);}
 const current=fileAreas.find(a=>a.id===area),d=await api('files?area='+encodeURIComponent(area)+'&path='+encodeURIComponent(currentPath));
 const attrs=current.writable&&user.role==='admin';
 $('#content').innerHTML=heading('Vos fichiers. Simplement.','Parcourez les espaces du NAS et gérez les volumes disponibles.',attrs?button('mkdir','Nouveau dossier','plus')+button('upload','Déposer un fichier','upload','primary'):'')+
 `<section class="card"><div class="toolbar"><select id="file-area" aria-label="Espace de fichiers">${fileAreas.map(a=>`<option value="${esc(a.id)}" ${a.id===area?'selected':''}>${esc(a.name)}${a.writable?'':' (lecture seule)'}</option>`).join('')}</select><div class="breadcrumb">${button('upfolder','↑ Dossier parent',null,'small',currentPath?'':'disabled')}<span>/${esc(currentPath)}</span></div><span class="spacer"></span>${button('trash-view','Corbeille','trash','small')}</div>${d.items.length?table(['Nom','Taille','Modification',''],d.items.map(item=>{const path=[currentPath,item.name].filter(Boolean).join('/');return `<tr><td><div class="file-name">${icon(item.directory?'folder':'file')}${item.directory&&!item.link?`<button data-action="openfolder" data-path="${esc(path)}">${esc(item.name)}</button>`:`<span>${esc(item.name)}${item.link?' (lien bloqué)':''}</span>`}</div></td><td>${item.directory?'—':sizes(item.size)}</td><td class="muted">${date(item.modified)}</td><td><div class="fileactions">${!item.directory&&!item.link?`<a class="iconbtn" aria-label="Télécharger ${esc(item.name)}" href="/api/download?area=${encodeURIComponent(area)}&path=${encodeURIComponent(path)}">${icon('download')}</a>`:''}${attrs?button('rename','','rename','iconbtn',`aria-label="Renommer ${esc(item.name)}" data-path="${esc(path)}" data-name="${esc(item.name)}"`)+button('trash','','trash','iconbtn danger',`aria-label="Mettre ${esc(item.name)} en corbeille" data-path="${esc(path)}"`):''}</div></td></tr>`;})):empty('Ce dossier est prêt à accueillir vos fichiers.')}</section><input type="file" id="upload-input" hidden><p class="capacity-note">${attrs?'Les fichiers mis en corbeille restent sur ce volume et peuvent être restaurés. Dépôt sans plafond applicatif de taille.':'Cet espace est proposé en lecture seule.'}</p>`;
}


async function renderCamera(){const [info,records,d,settings]=await Promise.all([api('camera/info'),api('camera/recordings'),api('overview'),api('camera/settings')]);cameraSettings=settings;const enabled=info.features?.includes('pt')&&user.role==='admin';$('#content').innerHTML=heading('Votre caméra, à portée de vue.','Tapo C530WS · direct local, pilotage manuel et enregistrements.',`${user.role==='admin'?button('camera-settings','Réglages',null,'small'):''}<a href="https://127.0.0.1:8971/" target="_blank" rel="noopener">Ouvrir Frigate ↗</a>`)+`<div class="camera-grid"><section class="card"><div class="cardhead"><h2>Caméra principale</h2><span class="badge"><span class="statusdot"></span>${d.camera.camera_fps>0?'En ligne':'Connexion en cours'}</span></div><div class="cameraimage"><img src="/api/camera/live" alt="Direct de la Tapo C530WS"><span class="live-tag"><span class="statusdot"></span>DIRECT · APERÇU 5 IMAGES/S</span></div><div class="camerafooter"><span>Enregistrement H.264 · 2880 × 1620 · audio AAC</span><span>Conservation : ${settings.days} jour(s)</span></div></section><section class="card"><div class="cardhead"><h2>Pilotage de la caméra</h2>${icon('camera')}</div><div class="ptz"><span class="badge ${enabled?'':'dim'}">${enabled?'PTZ disponible':'PTZ indisponible'}</span><div class="ptz-pad">${['blank','up','blank','left','stop','right','blank','down','blank'].map((dir,i)=>dir==='blank'?`<span class="blank" aria-hidden="true"></span>`:`<button data-action="ptz" data-direction="${dir}" class="${dir==='stop'?'stop':''}" aria-label="${{left:'Tourner à gauche',right:'Tourner à droite',up:'Monter',down:'Descendre',stop:'Arrêter la caméra'}[dir]}" ${enabled?'':'disabled'}>${icon(dir)}</button>`).join('')}</div><small>Chaque pression effectue un mouvement court.<br>Un ordre d’arrêt est envoyé automatiquement.</small>${info.presets?.length?`<div class="field"><label for="preset-select">Points de vue enregistrés</label><select id="preset-select">${info.presets.map(p=>`<option value="${esc(p)}">${esc(p)}</option>`).join('')}</select><button data-action="preset" ${enabled?'':'disabled'}>Aller au point de vue</button></div>`:''}<p class="capacity-note">Le suivi automatique reste désactivé.</p></div></section><section class="card wide"><div class="cardhead"><h2>Enregistrements récents</h2>${button('refresh-recordings','Actualiser',null,'small')}</div>${records.length?table(['Début','Durée','Taille',''],records.slice(-18).reverse().map(r=>`<tr><td>${date(r.start_time)}</td><td>${Math.round(r.duration)} s</td><td>${Number(r.segment_size || 0).toFixed(1)} Mo</td><td><button class="small" data-action="play" data-start="${r.start_time}" data-end="${r.end_time}">Lire le clip →</button></td></tr>`)):empty('Les nouveaux segments apparaîtront ici.','camera')}</section></div>`;}

async function renderStorage(){const [d,storage]=await Promise.all([api('overview'),api('storage')]);const pct=d.disk.used/d.disk.total*100;$('#content').innerHTML=heading('Disques et volumes.','Une vue du matériel détecté, indépendante de la marque du NAS.',button('refresh-storage','Actualiser',null,'small')+`<button data-page="native">Volumes natifs →</button>`)+`<div class="panelgrid"><section class="card"><div class="cardhead"><h2>Volume de l’application</h2><span class="badge">${esc(storage.current?.fstype||'Monté')}</span></div><div class="storagevisual"><div class="ring" id="storage-ring"><div class="ringinner"><strong>${pct.toFixed(1).replace('.',',')} %</strong><span>utilisé</span></div></div><div class="storagelegend"><div class="legendrow"><span>Capacité totale</span><b>${sizes(d.disk.total)}</b></div><div class="legendrow"><span>Espace utilisé</span><b>${sizes(d.disk.used)}</b></div><div class="legendrow"><span>Disponible</span><b>${sizes(d.disk.free)}</b></div></div></div></section><section class="card cardpad"><h2>Capacités du système</h2><div class="legendrow"><span>Plateforme</span><b>${esc(storage.platform)} · ${esc(storage.architecture)}</b></div><div class="legendrow"><span>Disques physiques</span><b>${storage.disks.length}</b></div><div class="legendrow"><span>Volumes détectés</span><b>${storage.volumes.length}</b></div><div class="legendrow"><span>Snapshots de fichiers</span><button class="small" data-page="snapshots">Ouvrir →</button></div><p class="capacity-note">Les snapshots de fichiers fonctionnent sur les volumes usuels. Les volumes Btrfs, ZFS ou LVM autorisés se pilotent depuis Volumes natifs.</p></section><section class="card wide"><div class="cardhead"><h2>Disques physiques</h2><span class="muted">NVMe · SATA · USB · contrôleurs détectés</span></div>${storage.disks.length?table(['Périphérique','Modèle / liaison','Capacité','État','Santé'],storage.disks.map(x=>`<tr><td>${esc(x.name)}${x.system?'<br><small class="muted">Disque système protégé</small>':''}</td><td>${esc(x.model||'Modèle non communiqué')}<br><small class="muted">${esc(x.transport)} · ${x.rotational?'Rotatif':'SSD / flash'}${x.removable?' · amovible':''}</small></td><td>${sizes(x.bytes)}</td><td>${x.readonly?'Lecture seule':'Accessible au système'}</td><td>${button('disk-health','Consulter SMART',null,'small',`data-id="${x.id}" ${storage.tools.smartctl?'':'disabled'}`)}</td></tr>`)):empty('Aucun disque physique exposé à ce service.','disk')}</section><section class="card wide"><div class="cardhead"><h2>Volumes et systèmes de fichiers</h2><span class="muted">Capacités réelles du matériel cible</span></div>${table(['Volume','Système','Montage','Snapshots natifs'],storage.volumes.map(v=>`<tr><td>${esc(v.name)}${v.label?'<br>'+esc(v.label):''}</td><td>${esc(v.filesystem)}</td><td>${v.mountpoints.map(esc).join('<br>')||'Non monté'}</td><td>${v.native_snapshot_family?esc(v.native_snapshot_family.toUpperCase())+' : capacité du système':'Non fournis par ce système de fichiers'}</td></tr>`))}</section></div><p class="capacity-note">SMART dépend du contrôleur et des droits accordés au service sur le matériel cible. Un diagnostic indisponible n’est pas assimilé à un disque sain. Cette console ne formate pas le disque système et ne le démonte pas.</p>`;$('#storage-ring').style.setProperty('--used',pct+'%');}

async function renderShares(){fileAreas=await api('areas');const d=await api('smb');currentSmb=d;$('#content').innerHTML=heading('Partagez, à votre manière.','Choisissez les dossiers accessibles et les comptes autorisés.',user.role==='admin'?button('share-create','Nouveau partage','plus','primary'):'')+`<div class="notice neutral">Accès SMB sur votre poste : <strong>127.0.0.1:1445</strong> via le tunnel SSH. Le service reste limité à l’accès local.</div><section class="card">${table(['Partage','Dossier','Accès','Comptes',''],d.shares.map(s=>`<tr><td><div class="file-name">${icon('share')}<strong>${esc(s.name)}</strong></div></td><td>${esc(fileAreas.find(a=>a.id===s.area)?.name||'Volume indisponible')}${s.path?' / '+esc(s.path):''}<br><small class="muted">${s.available?'Disponible':'Volume absent ou partage suspendu'}</small></td><td><span class="badge ${s.readonly?'dim':''}">${s.readonly?'Lecture seule':'Lecture et écriture'}</span></td><td>${s.users.map(esc).join(', ')}</td><td>${user.role==='admin'?button('share-edit','Configurer',null,'small',`data-name="${esc(s.name)}"`):''}</td></tr>`))}</section>`;}

async function renderUsers(){const [users,smb]=await Promise.all([api('users'),api('smb')]);currentSmb=smb;webUsers=users;$('#content').innerHTML=heading('Les bons accès, aux bonnes personnes.','Les comptes de console et les comptes de partage ont des usages distincts.')+`<div class="stack"><section class="card"><div class="cardhead"><h2>Comptes de la console</h2>${user.role==='admin'?button('webuser-create','Ajouter un compte','plus','small'):''}</div>${table(['Identifiant','Rôle','Accès',''],users.map(u=>`<tr><td>${esc(u.name)}</td><td><span class="badge ${u.role==='admin'?'':'dim'}">${u.role==='admin'?'Administrateur':'Lecture seule'}</span></td><td>${!u.active?'Compte désactivé':u.role==='admin'?'Gestion des fichiers, services, partages et caméra':'Consultation et téléchargement'}</td><td>${user.role==='admin'?button('webuser-edit','Gérer',null,'small',`data-name="${esc(u.name)}"`):''}</td></tr>`))}</section><section class="card"><div class="cardhead"><h2>Comptes de partage SMB</h2>${user.role==='admin'?button('smbuser-create','Ajouter un compte','plus','small'):''}</div>${table(['Identifiant','État','Usage',''],smb.users.map(u=>`<tr><td>${esc(u.name)}</td><td><span class="badge ${u.enabled?'':'dim'}">${u.enabled?'Actif':'Désactivé'}</span></td><td>Accès aux dossiers autorisés dans les partages</td><td>${user.role==='admin'?button('smbuser-edit','Gérer',null,'small',`data-name="${esc(u.name)}"`):''}</td></tr>`))}</section></div>`;}

async function renderServices(){const d=await api('overview');$('#content').innerHTML=heading('Vos services essentiels.','Démarrez, arrêtez ou relancez les services de ce NAS depuis la console.')+`<div class="stack">${d.services.map(s=>`<section class="card cardpad"><div class="row"><span class="appicon">${icon(s.name==='video'?'camera':'folder')}</span><div><h2>${s.name==='video'?'Vidéosurveillance · Frigate':'Partage de fichiers · Samba'}</h2><p class="muted">${esc(s.status)}${s.health?' · '+esc(s.health):''}</p></div><span class="badge ${s.state==='running'?'':'dim'}">${s.state==='running'?'En ligne':'Arrêté'}</span></div>${user.role==='admin'?`<div class="service-control">${['start','restart','stop'].map(a=>button('service',{'start':'Démarrer','restart':'Redémarrer','stop':'Arrêter'}[a],null,'small',`data-name="${s.name}" data-operation="${a}" ${a==='start'&&s.state==='running'?'disabled':''}`)).join('')}</div>`:''}</section>`).join('')}</div><p class="capacity-note">Arrêter ou redémarrer la vidéo interrompt temporairement l’enregistrement. Les autres projets hébergés sur NAS ne sont pas pilotés par cette console.</p>`;}

async function renderBackups(){await loadProtection();const [files,jobs]=await Promise.all([api('files?area=sauvegardes'),api('jobs')]);$('#content').innerHTML=heading('Sauvegardes, à votre rythme.','Archives à la demande et plans automatiques configurables pour le matériel cible.',user.role==='admin'?button('plan-create','Nouveau plan','plus')+button('backup','Créer une archive','backup','primary'):'')+`<div class="notice">Aucun plafond applicatif de taille ni de nombre de fichiers. Les transferts et archives sont traités en flux, dans la limite de l’espace physique disponible.</div><section class="card"><div class="cardhead"><h2>Plans automatiques</h2><span class="muted">Désactivés par défaut</span></div>${protectionPlans.length?table(['Plan','Horaire','État','Prochain passage',''],protectionPlans.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.config.time)} · ${esc(p.config.timezone)}<br><small class="muted">${p.config.weekdays.length===7?'Chaque jour':p.config.weekdays.map(x=>['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'][x]).join(', ')}</small></td><td><span class="badge ${p.enabled?'':'dim'}">${p.enabled?'Actif':'Désactivé'}</span></td><td>${p.next_run?date(p.next_run):'Aucun passage programmé'}</td><td>${button('plan-edit','Configurer',null,'small',`data-id="${p.id}"`)} ${button('plan-run','Exécuter maintenant',null,'small',`data-id="${p.id}" ${snapshotRepo?'':'disabled'}`)}</td></tr>`)):empty('Aucun plan configuré. Choisissez d’abord une destination et votre horaire.','backup')}</section><br><section class="card"><div class="cardhead"><h2>Tâches et progression</h2>${button('refresh-backups','Actualiser',null,'small')}</div>${jobs.length?table(['Date','Opération','État','Résultat',''],jobRows(jobs)):empty('Les tâches sont conservées et peuvent continuer après fermeture du navigateur.','activity')}</section><br><section class="card"><div class="cardhead"><h2>Archives disponibles</h2><span class="muted">${files.items.length} archive(s)</span></div>${files.items.length?table(['Nom','Taille','Création',''],files.items.map(f=>`<tr><td>${esc(f.name)}</td><td>${sizes(f.size)}</td><td>${date(f.modified)}</td><td><a href="/api/download?area=sauvegardes&path=${encodeURIComponent(f.name)}">Télécharger ↓</a></td></tr>`)):empty('Les archives manuelles apparaîtront ici.','backup')}</section><p class="capacity-note">Les plans utilisent un dépôt chiffré et dédupliqué. Rien ne s’exécute automatiquement avant activation explicite. Les points sont conservés ; aucune politique de suppression automatique n’est appliquée.</p>`;}

async function renderEvents(){const events=await api('events');$('#content').innerHTML=heading('Une trace de vos actions.','Connexions et opérations effectuées dans cette console locale.')+`<section class="card">${events.length?table(['Date','Compte','Action','Détail'],events.map(e=>`<tr><td>${date(e.ts)}</td><td>${esc(e.username)}</td><td>${esc(e.action)}</td><td>${esc(e.detail)}</td></tr>`)):empty('Le journal est encore vide.','activity')}</section>`;}
async function renderTrash(){const items=await api('trash');$('#content').innerHTML=heading('Une seconde chance pour vos fichiers.','Les éléments restent récupérables tant que vous les laissez dans cette corbeille.',button('back-files','Retour aux fichiers','folder'))+`<section class="card">${items.length?table(['Chemin d’origine','Déplacement',''],items.map(i=>`<tr><td><small class="muted">${esc(fileAreas.find(a=>a.id===(i.area||'fichiers'))?.name||i.area||'Fichiers partagés')}</small><br>${esc(i.original)}</td><td>${date(i.ts)}</td><td>${user.role==='admin'?button('restore','Restaurer','backup','small',`data-id="${esc(i.id)}"`):''}</td></tr>`)):empty('La corbeille est vide.','trash')}</section>`;}

function modal(title,content,submitLabel,submit){const m=$('#modal');m.innerHTML=`<form id="modal-form"><div class="modalhead"><h2>${esc(title)}</h2><button type="button" class="iconbtn" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><div class="modalbody">${content}<p id="modal-error" class="error"></p><div class="modalfoot"><button type="button" data-action="close-modal">Annuler</button><button class="primary" type="submit">${submitLabel}</button></div></div></form>`;modalSubmit=submit;m.showModal();}
function confirmAction(title,text,submit,task){modal(title,`<p class="muted">${esc(text)}</p>`,submit,task);}
function shareModal(existing){const s=existing || {name:'',path:'',area:'fichiers',readonly:false,users:['nas']};modal(existing?'Configurer le partage':'Nouveau partage',field('Nom du partage','name',s.name)+`<div class="field"><label for="share-area">Espace</label><select id="share-area" name="area">${fileAreas.filter(a=>['fichiers','video'].includes(a.id)||a.kind==='volume').map(a=>`<option value="${esc(a.id)}" ${a.id===s.area?'selected':''}>${esc(a.name)}</option>`).join('')}${fileAreas.some(a=>a.id===s.area)?'':`<option value="${esc(s.area)}" selected>Volume indisponible</option>`}</select></div>`+`<div class="field"><label for="field-path">Dossier existant (vide = racine)</label><input id="field-path" name="path" value="${esc(s.path)}"></div><div class="checks"><label><input type="checkbox" name="readonly" ${s.readonly?'checked':''}>Lecture seule</label></div><div class="field"><label>Comptes autorisés</label><div class="checks">${currentSmb.users.filter(u=>u.enabled).map(u=>`<label><input type="checkbox" name="users" value="${esc(u.name)}" ${s.users.includes(u.name)?'checked':''}>${esc(u.name)}</label>`).join('')}</div></div>`,'Enregistrer',async form=>{const b=Object.fromEntries(form);b.users=form.getAll('users');b.readonly=form.has('readonly');await api('smb/share',b);});}

document.addEventListener('click',async e=>{const el=e.target.closest('[data-page],[data-action]');if(!el)return;e.preventDefault();if(el.dataset.page)return go(el.dataset.page);const action=el.dataset.action;try{
switch(action){case 'logout':await api('logout',{});return login();case 'close-modal':return $('#modal').close();case 'mkdir':return modal('Créer un dossier',field('Nom du dossier','name'),'Créer',async f=>{await api('folder',{name:f.get('name'),path:currentPath,area});});case 'upload':return $('#upload-input').click();case 'openfolder':currentPath=el.dataset.path;return renderFiles();case 'upfolder':currentPath=currentPath.split('/').slice(0,-1).join('/');return renderFiles();case 'trash-view':return go('trash');case 'back-files':return go('files');case 'rename':return modal('Renommer',field('Nouveau nom','name',el.dataset.name),'Renommer',async f=>api('rename',{path:el.dataset.path,name:f.get('name'),area}));case 'trash':return confirmAction('Mettre en corbeille ?',el.dataset.path+' sera déplacé dans la corbeille et pourra être restauré.','Déplacer',async()=>api('trash',{path:el.dataset.path,area}));case 'restore':await api('restore',{id:el.dataset.id});toast('Élément restauré.');return renderTrash();case 'ptz':el.disabled=true;try{await api('camera/ptz',{action:el.dataset.direction});}finally{el.disabled=false;}return;case 'camera-settings':return modal('Réglages de la caméra',`<p class="muted">L’application des réglages redémarre brièvement le service vidéo. Une durée plus courte entraîne la suppression automatique des segments les plus anciens.</p><div class="field"><label for="retention-days">Conservation continue (jours)</label><input id="retention-days" type="number" min="1" max="30" name="days" value="${cameraSettings.days}" required></div><div class="checks"><label><input type="checkbox" name="enabled" ${cameraSettings.enabled?'checked':''}>Caméra active</label></div>`,'Appliquer les réglages',async f=>api('camera/settings',{days:Number(f.get('days')),enabled:f.has('enabled')}));case 'preset':await api('camera/ptz',{action:'preset',preset:$('#preset-select').value});toast('Commande envoyée au point de vue enregistré.');return;case 'refresh-recordings':return renderCamera();case 'play':{const m=$('#modal');m.innerHTML=`<div class="modalhead"><h2>Clip du ${date(Number(el.dataset.start))}</h2><button class="iconbtn" data-action="close-modal" aria-label="Fermer">${icon('close')}</button></div><video class="recordvideo" controls autoplay src="/api/camera/clip?start=${el.dataset.start}&end=${el.dataset.end}"></video>`;m.showModal();return;}case 'share-create':return shareModal();case 'share-edit':return shareModal(currentSmb.shares.find(s=>s.name===el.dataset.name));case 'webuser-create':return modal('Ajouter un compte console',field('Identifiant','name')+field('Mot de passe','password','','password','12 caractères minimum.')+`<div class="field"><label for="role">Rôle</label><select id="role" name="role"><option value="viewer">Lecture seule</option><option value="admin">Administrateur</option></select></div>`,'Créer le compte',async f=>api('user',Object.fromEntries(f)));case 'webuser-edit':{const u=webUsers.find(u=>u.name===el.dataset.name);return modal('Gérer le compte '+u.name,`<div class="field"><label for="user-role">Rôle</label><select id="user-role" name="role"><option value="viewer" ${u.role==='viewer'?'selected':''}>Lecture seule</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrateur</option></select></div><div class="checks"><label><input type="checkbox" name="active" ${u.active?'checked':''}>Compte actif</label></div><div class="field"><label for="new-password">Nouveau mot de passe (optionnel)</label><input id="new-password" type="password" name="password" autocomplete="new-password"><small>Laisser vide pour conserver le mot de passe actuel.</small></div>`,'Enregistrer',async f=>api('user/update',{name:u.name,role:f.get('role'),active:f.has('active'),password:f.get('password')}));}case 'smbuser-create':return modal('Ajouter un compte SMB',field('Identifiant','name')+field('Mot de passe','password','','password','12 caractères minimum. Choisissez ensuite ses partages autorisés.'),'Créer le compte',async f=>api('smb/user',{...Object.fromEntries(f),enabled:true}));case 'smbuser-edit':{const u=currentSmb.users.find(u=>u.name===el.dataset.name);return modal('Gérer le compte '+u.name,`<p class="muted">Le compte initial nas est conservé actif. Les modifications concernent uniquement le partage SMB.</p><div class="field"><label for="new-smb-password">Nouveau mot de passe (optionnel)</label><input id="new-smb-password" type="password" name="password" autocomplete="new-password"><small>Laisser vide pour conserver le mot de passe actuel.</small></div><div class="checks"><label><input type="checkbox" name="enabled" ${u.enabled?'checked':''} ${u.name==='nas'?'disabled':''}>Compte actif</label></div>`,'Enregistrer',async f=>api('smb/user',{name:u.name,enabled:u.name==='nas'||f.has('enabled'),password:f.get('password')}));}case 'service':return confirmAction('Confirmer l’action sur le service',el.dataset.name==='video'?'Cette action peut interrompre temporairement le direct et l’enregistrement.':'Cette action peut interrompre temporairement les accès aux fichiers.','Continuer',async()=>api('service',{name:el.dataset.name,action:el.dataset.operation}));case 'backup':return confirmAction('Créer une archive des fichiers partagés','Une archive sera créée en flux, sans plafond applicatif de taille ni de nombre de fichiers, selon l’espace physique disponible.','Créer la sauvegarde',async()=>{await api('backup',{});});case 'refresh-backups':return renderBackups();}
}catch(error){toast(error.message,true);}});

document.addEventListener('submit',async e=>{if(e.target.id==='login-form'){e.preventDefault();const form=new FormData(e.target),button=e.target.querySelector('button[type=submit]');button.disabled=true;try{user=await api('login',Object.fromEntries(form));try{user=await api('me');}catch(error){if(error.status===401)throw new Error('Le navigateur ne transmet pas la session de connexion. Vérifiez les cookies autorisés pour cette adresse, puis réessayez.');throw error;}shell();await go(location.hash.slice(1)||'home');startRefresh();}catch(error){const message=$('#login-error');if(message)message.textContent=error.message;else if(error.name!=='AbortError')toast(error.message,true);}finally{button.disabled=false;}}else if(e.target.id==='modal-form'){e.preventDefault();const form=new FormData(e.target),button=e.target.querySelector('button[type=submit]');button.disabled=true;try{await modalSubmit(form);$('#modal').close();toast('Opération effectuée.');await render();}catch(error){if($('#modal-error'))$('#modal-error').textContent=error.message;else toast(error.message,true);}finally{button.disabled=false;}}});
document.addEventListener('change',async e=>{if(e.target.id==='file-area'){area=e.target.value;currentPath='';return renderFiles();}if(e.target.id==='upload-input'){const file=e.target.files[0];if(!file)return;try{await uploadFile(file);toast('Fichier déposé.');await renderFiles();}catch(error){toast(error.message,true);}}});
$('#modal').addEventListener('close',()=>{$('#modal').querySelector('video')?.pause();$('#modal').innerHTML='';modalSubmit=null;});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&user&&page==='camera')api('camera/ptz',{action:'stop'}).catch(()=>{});});
function startRefresh(){clearInterval(refreshTimer);if(!user)return;refreshTimer=setInterval(async()=>{if(!user||document.hidden||$('#modal').open)return;$('#topclock').textContent=date(Date.now()/1000);if(page==='home')await renderHome().catch(()=>{});if(page==='backups')await renderBackups().catch(()=>{});if(page==='snapshots')await renderSnapshots().catch(()=>{});if(page==='native')await renderNative().catch(()=>{});},10000);}
document.addEventListener('DOMContentLoaded',async()=>{try{user=await api('me');shell();await go(location.hash.slice(1)||'home');startRefresh();}catch{login();}},{once:true});

window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(user&&titles[next]&&next!==page)go(next);});

let protectionRepos=[], protectionTargets=[], protectionPlans=[], snapshotRepo='';
function jobRows(jobs){return jobs.map(j=>{const r=JSON.parse(j.result||'{}'),p=JSON.parse(j.progress||'{}');const labels={backup:'Archive de fichiers',snapshot:'Snapshot de fichiers',snapshot_restore:'Restauration'};const states={done:'Terminée',partial:'Partielle',running:'En cours',queued:'En attente',failed:'Échec',cancelled:'Annulée'};const running=['running','queued'].includes(j.status);return `<tr><td>${date(j.ts)}</td><td>${esc(labels[j.kind]||j.kind)}</td><td><span class="badge ${j.status==='done'?'':j.status==='failed'||j.status==='partial'?'warn':'dim'}">${states[j.status]||esc(j.status)}</span>${running?`<div class="job-progress">${p.percent_done!==undefined?`<progress max="1" value="${Number(p.percent_done)}"></progress>`:''}<small>${p.bytes_done!==undefined?sizes(p.bytes_done)+(p.total_bytes?' / '+sizes(p.total_bytes):''):'Préparation…'}</small></div>`:''}</td><td>${esc(r.file||r.warning||r.error||r.label||'')}${r.directory?`<button class="small" data-action="open-restoration" data-directory="${esc(r.directory)}">Parcourir la restauration →</button>`:''}</td><td>${running&&user.role==='admin'?button('job-cancel','Annuler',null,'small',`data-job="${esc(j.id)}"`):''}</td></tr>`;});}
async function loadProtection(){if(user.role!=='admin')return;protectionSources=await api('protection/sources');[protectionRepos,protectionTargets,protectionPlans]=await Promise.all([api('protection/repositories'),api('protection/targets'),api('protection/plans')]);}


async function renderSnapshots(){if(user.role!=='admin'){$('#content').innerHTML=empty('La protection des données est réservée aux administrateurs.','lock');return;}await loadProtection();const capabilities=await api('protection/capabilities');const migrations=await api('protection/migrations');const installation=await api('protection/installation');if(!protectionRepos.some(r=>r.id===snapshotRepo))snapshotRepo=protectionRepos[0]?.id||'';const points=snapshotRepo&&protectionRepos.find(r=>r.id===snapshotRepo)?.target!=='recovery-detached'?await api('protection/points?repo='+snapshotRepo):[];const jobs=await api('jobs');$('#content').innerHTML=heading('Retrouvez une version de vos fichiers.','Points de restauration chiffrés et dédupliqués, indépendants du modèle de NAS.',button('repo-create','Ajouter un dépôt','plus')+button('snapshot-create','Créer un snapshot','backup','primary',protectionRepos.length&&capabilities.available?'':'disabled'))+`<div class="notice ${capabilities.available?'':'neutral'}">${capabilities.available?'Moteur de snapshots disponible.':'Le runtime de protection doit être installé sur le serveur cible.'} Il s’agit de <strong>snapshots de fichiers</strong>, qui ne figent pas atomiquement tout un volume. Choisissez une destination pour activer la protection.</div><section class="card"><div class="cardhead"><h2>Dépôts de protection</h2><span class="muted">${esc(capabilities.version||'Runtime restic non installé')}</span></div>${protectionRepos.length?table(['Nom','Destination','Création',''],protectionRepos.map(r=>`<tr><td>${esc(r.name)}${r.target==='recovery-detached'?'<br><span class="muted">À raccorder après reprise</span>':''}</td><td>${esc(r.path)}</td><td>${date(r.created)}</td><td><a href="/api/protection/recovery?repo=${r.id}" download>Clé de récupération ↓</a></td></tr>`)):empty('Aucun dépôt. Vous pourrez choisir un volume local ou un disque/NAS déjà monté.','disk')}</section><br><section class="card"><div class="cardhead"><h2>Points de restauration</h2>${protectionRepos.length?`<select id="snapshot-repo" aria-label="Dépôt des snapshots">${protectionRepos.map(r=>`<option value="${r.id}" ${r.id===snapshotRepo?'selected':''}>${esc(r.name)}</option>`).join('')}</select>`:''}</div>${points.length?table(['Date','Identifiant','Fichiers','Taille logique',''],points.slice().reverse().map(p=>`<tr><td>${date(Date.parse(p.time)/1000)}</td><td>${esc(p.short_id||p.id.slice(0,8))}</td><td>${p.summary?.total_files_processed??'—'}</td><td>${sizes(p.summary?.total_bytes_processed)}</td><td>${button('restore-point','Restaurer…',null,'small',`data-id="${p.id}" ${snapshotRepo?'':'disabled'}`)}</td></tr>`)):empty('Les versions apparaîtront ici après une première capture.','backup')}</section><br><section class="card"><div class="cardhead"><h2>Dernières tâches de protection</h2>${button('refresh-snapshots','Actualiser',null,'small')}</div>${jobs.some(j=>j.kind!=='backup')?table(['Date','Opération','État','Résultat',''],jobRows(jobs.filter(j=>j.kind!=='backup'))):empty('Aucune opération effectuée.','activity')}</section><br><section class="card"><div class="cardhead"><h2>Reprise de l’installation</h2>${button('installation-help','Préparer la reprise',null,'small')}</div><div class="recovery-details"><p>Fichiers et vidéos, configuration, comptes web, clés chiffrées et identité Samba réunis dans une capture hors ligne.</p><div class="legendrow"><span>Clés de dépôts présentes</span><b>${installation.repositories-installation.missing_keys} / ${installation.repositories}</b></div><div class="legendrow"><span>Dernière capture validée sur cette installation</span><b>${installation.last_capture?.complete?date(Date.parse(installation.last_capture.created)/1000):'Aucune capture validée'}</b></div>${installation.missing_keys?'<p class="notice">Une clé manque ou ses permissions ne sont pas privées. La capture complète sera refusée.</p>':''}${installation.restoration?`<div class="legendrow"><span>État Samba récupéré</span><b>${installation.restoration.samba_ready?'Prêt pour vérification':'Import à effectuer'}</b></div><p class="muted">${installation.detached_repositories} dépôt(s) à raccorder après contrôle de leur identité. ${installation.enabled_plans} plan(s) actuellement actif(s).</p>`:''}<p class="muted">La préparation crée une nouvelle installation, conserve les comptes et désactive les sauvegardes automatiques. La clé de reprise doit être conservée sur un support distinct. Le système Linux et la reconstruction des disques demandent une préparation séparée.</p></div></section><br><section class="card"><div class="cardhead"><h2>Reprise de la console</h2>${button('migration-help','Comprendre la récupération',null,'small')}</div><div class="recovery-details"><p>Base de console · version ${esc(migrations.schema_version)}. Une copie privée précède chaque évolution de sa structure.</p>${migrations.checkpoints.length?table(['Copie préalable','Création','Taille'],migrations.checkpoints.slice().reverse().map(m=>`<tr><td>Avant migration ${esc(m.source_version)} → ${esc(m.target_version)}</td><td>${date(Date.parse(m.created)/1000)}</td><td>${sizes(m.bytes)}</td></tr>`)): '<p class="muted">Aucune migration d’une base existante n’a encore nécessité de copie.</p>'}<p class="muted">Ces copies locales concernent les comptes et réglages enregistrés dans la base. Les fichiers, vidéos et clés des dépôts nécessitent leur propre sauvegarde. La récupération vérifie l’empreinte et prépare un nouveau fichier hors ligne.</p></div></section><p class="capacity-note">La restauration écrit dans un nouveau dossier privé, sans écraser les fichiers actuels. Les restaurations de configuration sont réservées aux administrateurs. Conservez la clé de récupération sur un support distinct du dépôt.</p>`;}
function repoOptions(selected=''){return protectionRepos.map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(r.name)}</option>`).join('');}
function dataChoices(value={configuration:true,video:false}){
 const chosen=value.sources||['fichiers'];
 const available=new Set(protectionSources.map(s=>s.id));
 return `<div class="field"><label>Espaces de fichiers</label><div class="checks">${protectionSources.map(s=>`<label><input type="checkbox" name="sources" value="${esc(s.id)}" ${chosen.includes(s.id)?'checked':''}>${esc(s.name)}</label>`).join('')}${chosen.filter(id=>!available.has(id)).map(id=>`<label><input type="checkbox" name="sources" value="${esc(id)}" checked>Volume indisponible (${esc(id.slice(-8))})</label>`).join('')}</div></div><div class="checks"><label><input type="checkbox" name="configuration" ${value.configuration?'checked':''}>Configuration du NAS</label><label><input type="checkbox" name="video" ${value.video?'checked':''}>Enregistrements vidéo</label></div><p class="capacity-note">Les espaces sélectionnés sont capturés dans le dépôt chiffré. Les corbeilles et dépôts internes sont exclus. Cette capture ne fige pas simultanément tous les volumes.</p>`;
}

function planModal(existing){const p=existing||{name:'',repo:protectionRepos[0]?.id||'',enabled:false,config:{time:'02:00',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',weekdays:[0,1,2,3,4,5,6],configuration:true,video:false}};modal(existing?'Configurer le plan':'Nouveau plan automatique',field('Nom du plan','name',p.name)+`<div class="field"><label for="plan-repo">Dépôt</label><select id="plan-repo" name="repo"><option value="">À choisir sur le matériel cible</option>${repoOptions(p.repo)}</select></div>`+field('Heure locale','time',p.config.time,'time')+field('Fuseau horaire IANA','timezone',p.config.timezone)+`<div class="field"><label>Jours d’exécution</label><div class="checks">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map((d,i)=>`<label><input type="checkbox" name="weekdays" value="${i}" ${p.config.weekdays.includes(i)?'checked':''}>${d}</label>`).join('')}</div></div>`+dataChoices(p.config)+`<div class="checks"><label><input type="checkbox" name="enabled" ${p.enabled?'checked':''}>Activer ce plan</label></div><p class="capacity-note">Un brouillon peut être conservé sans destination. L’activation nécessite un dépôt configuré sur le matériel cible.</p>`,'Enregistrer le plan',async f=>api('protection/plan',{id:existing?.id,name:f.get('name'),repo:f.get('repo'),time:f.get('time'),timezone:f.get('timezone'),weekdays:f.getAll('weekdays').map(Number),sources:f.getAll('sources'),configuration:f.has('configuration'),video:f.has('video'),enabled:f.has('enabled')}));}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;try{switch(a){case 'refresh-storage':return renderStorage();case 'disk-health':{toast('Lecture des informations SMART…');const d=await api('storage/health?id='+el.dataset.id);modal('Diagnostic SMART',`<p class="muted">${esc(d.message||({ok:'Le contrôleur déclare un état sain.',warning:'Le contrôleur déclare une alerte.',unknown:'État de santé non communiqué.'}[d.state])||d.state)}</p>${d.temperature!==undefined?`<div class="legendrow"><span>Température</span><b>${esc(d.temperature??'—')} °C</b></div>`:''}${d.power_on_hours!==undefined?`<div class="legendrow"><span>Heures de fonctionnement</span><b>${esc(d.power_on_hours??'—')}</b></div>`:''}${d.media_errors!==undefined?`<div class="legendrow"><span>Erreurs média</span><b>${esc(d.media_errors??'—')}</b></div>`:''}`,'Fermer',async()=>{});return;}case 'repo-create':return modal('Ajouter un dépôt chiffré',field('Nom du dépôt','name')+`<div class="field"><label for="repo-target">Destination disponible</label><select id="repo-target" name="target">${protectionTargets.map(t=>`<option value="${esc(t.id)}">${esc(t.label)}</option>`).join('')}</select></div>`+field('Clé de chiffrement','password','','password','12 caractères minimum. Conservez cette clé pour pouvoir restaurer sur un autre matériel.')+`<p class="capacity-note">Un nouveau dépôt dédié sera créé dans la destination choisie. Aucun fichier existant n’est remplacé et aucun plan n’est activé.</p>`,'Créer le dépôt',async f=>api('protection/repository',Object.fromEntries(f)));case 'snapshot-create':return modal('Créer un snapshot de fichiers',field('Libellé','label','Point manuel')+`<div class="field"><label for="snapshot-target">Dépôt</label><select id="snapshot-target" name="repo">${repoOptions(snapshotRepo)}</select></div>`+dataChoices(),'Créer le point',async f=>api('protection/snapshot',{repo:f.get('repo'),label:f.get('label'),sources:f.getAll('sources'),configuration:f.has('configuration'),video:f.has('video')}));case 'restore-point':return confirmAction('Restaurer dans un nouveau dossier','Les données seront restaurées dans un espace privé séparé. Les fichiers actuels ne seront pas écrasés.','Restaurer',async()=>api('protection/restore',{repo:snapshotRepo,snapshot:el.dataset.id}));case 'installation-help':return modal('Préparer une reprise complète de Nacre',`<p><strong>1. Conserver la clé hors du NAS.</strong> Initialiser un dépôt de reprise dédié sur un support indépendant et garder sa clé privée séparément.</p><p><strong>2. Capturer à l’arrêt.</strong> Arrêter la console, ses tâches, Samba et la vidéo. Inclure tous les volumes externes et exporter les métadonnées natives si le service est installé.</p><p><strong>3. Préparer une nouvelle installation.</strong> Vérifier les données, importer l’état Samba, puis rattacher les dépôts avec les clés retrouvées. Les anciens accès temporaires sont révoqués et les plans restent désactivés.</p><p>Le parcours actuel exige la même architecture et les mêmes UID/GID du compte principal. Les données des volumes natifs sont récupérées en dossiers ordinaires ; leur topologie et leurs anciens snapshots ne sont pas recréés automatiquement.</p><p>Procédure détaillée : <strong>docs/SYSTEM-RECOVERY.md</strong>. Outil : <code>python3 console/system_recovery.py --help</code>. Aucun arrêt ni capture n’est déclenché depuis cet écran.</p>`,'Fermer',async()=>{});case 'migration-help':return modal('Récupérer la base de console',`<p>Une mise à jour de la structure conserve d’abord une copie privée et vérifiée. Si la migration échoue, les modifications de la base sont annulées.</p><p>La préparation hors ligne vérifie la copie et crée un <strong>nouveau fichier</strong>. Les anciens accès temporaires sont révoqués, les plans désactivés et les tâches en cours signalées comme interrompues.</p><p>Un administrateur doit arrêter la console et ses tâches, vérifier la configuration et les clés correspondantes, puis suivre la procédure de reprise avant toute remise en service. Aucun remplacement de la base active n’est lancé depuis cet écran.</p><p>Procédure dans le dépôt : <strong>docs/RECOVERY.md</strong>. Outil serveur : <code>python3 console/recover_database.py --help</code>.</p>`,'Fermer',async()=>{});case 'refresh-snapshots':return renderSnapshots();case 'plan-create':return planModal();case 'plan-edit':return planModal(protectionPlans.find(p=>p.id===el.dataset.id));case 'plan-run':return confirmAction('Exécuter ce plan maintenant','Une capture sera créée dans le dépôt choisi. Cela n’active pas les prochaines exécutions du plan.','Exécuter',async()=>api('protection/run-plan',{id:el.dataset.id}));case 'job-cancel':await api('protection/cancel',{job:el.dataset.job});toast('Annulation demandée.');return render();case 'open-restoration':area='restaurations';currentPath=el.dataset.directory;return go('files');case 'upload-cancel':activeUpload?.abort();return;}}catch(error){toast(error.message,true);}});
document.addEventListener('change',e=>{if(e.target.id==='snapshot-repo'){snapshotRepo=e.target.value;renderSnapshots().catch(error=>toast(error.message,true));}});
let activeUpload=null;
function uploadFile(file){return new Promise((resolve,reject)=>{if(activeUpload){reject(new Error('Un transfert est déjà en cours.'));return;}const xhr=new XMLHttpRequest();activeUpload=xhr;let panel=$('#transfer-panel');if(!panel){panel=document.createElement('div');panel.id='transfer-panel';document.body.append(panel);}panel.innerHTML=`<strong>${esc(file.name)}</strong><progress max="1" value="0"></progress><span>Préparation du transfert…</span>${button('upload-cancel','Annuler',null,'small')}`;xhr.open('POST','/api/upload?area='+encodeURIComponent(area)+'&path='+encodeURIComponent(currentPath)+'&name='+encodeURIComponent(file.name));xhr.setRequestHeader('X-CSRF-Token',user.csrf);xhr.setRequestHeader('Content-Type','application/octet-stream');xhr.upload.onprogress=e=>{if(e.lengthComputable){panel.querySelector('progress').value=e.total?e.loaded/e.total:1;panel.querySelector('span').textContent=sizes(e.loaded)+' / '+sizes(e.total);}};const cleanup=()=>{activeUpload=null;panel.remove();};xhr.onload=()=>{cleanup();let result;try{result=JSON.parse(xhr.responseText);}catch{reject(new Error('Réponse de transfert invalide.'));return;}if(xhr.status>=200&&xhr.status<300)resolve(result);else reject(new Error(result.error||'Transfert non abouti.'));};xhr.onerror=()=>{cleanup();reject(new Error('Connexion interrompue. Aucun fichier existant n’a été remplacé.'));};xhr.onabort=()=>{cleanup();reject(new Error('Transfert annulé.'));};xhr.send(file);});}
